
import json
with open('knowledge/bbmp_wards.json') as f:
    WARDS = json.load(f)

def map_to_ward(lat: float, lon: float):
    """Tool generated by Bob - GIS ward mapping"""
    # Simplified point-in-polygon lookup
    for ward in WARDS:
        if ward["min_lat"] <= lat <= ward["max_lat"] and ward["min_lon"] <= lon <= ward["max_lon"]:
            return ward
    return {"ward_id": "UNKNOWN", "je_name": "Central Control", "dept": "BBMP"}
